//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_AttackStatusRx(value: *mut SW::AttackStatus) -> bool;
  fn get_AttackStatusRx_num_invalid() -> u64;
  fn get_AttackStatusTx(value: *mut SW::AttackStatus) -> bool;
  fn get_AttackStatusTx_num_invalid() -> u64;
  fn put_CurrentMode(value: *mut SW::Mode) -> bool;
}

pub fn unsafe_get_AttackStatusRx() -> SW::AttackStatus
{
  unsafe {
    let value: *mut SW::AttackStatus = &mut SW::AttackStatus::default();
    get_AttackStatusRx(value);
    return *value;
  }
}

pub fn unsafe_get_AttackStatusRx_num_invalid() -> u64
{
  unsafe {
    return get_AttackStatusRx_num_invalid();
  }
}

pub fn unsafe_get_AttackStatusTx() -> SW::AttackStatus
{
  unsafe {
    let value: *mut SW::AttackStatus = &mut SW::AttackStatus::default();
    get_AttackStatusTx(value);
    return *value;
  }
}

pub fn unsafe_get_AttackStatusTx_num_invalid() -> u64
{
  unsafe {
    return get_AttackStatusTx_num_invalid();
  }
}

pub fn unsafe_put_CurrentMode(value: &SW::Mode) -> bool
{
  unsafe {
    return put_CurrentMode(value as *const SW::Mode as *mut SW::Mode);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_AttackStatusRx: Mutex<Option<SW::AttackStatus>> = Mutex::new(None);
  pub static ref IN_AttackStatusTx: Mutex<Option<SW::AttackStatus>> = Mutex::new(None);
  pub static ref OUT_CurrentMode: Mutex<Option<SW::Mode>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_AttackStatusRx.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_AttackStatusTx.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_CurrentMode.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_AttackStatusRx(value: *mut SW::AttackStatus) -> bool
{
  unsafe {
    let guard = IN_AttackStatusRx.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_AttackStatusRx_num_invalid() -> u64
{
  return 0;
}

#[cfg(test)]
pub fn get_AttackStatusTx(value: *mut SW::AttackStatus) -> bool
{
  unsafe {
    let guard = IN_AttackStatusTx.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_AttackStatusTx_num_invalid() -> u64
{
  return 0;
}

#[cfg(test)]
pub fn put_CurrentMode(value: *mut SW::Mode) -> bool
{
  unsafe {
    *OUT_CurrentMode.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
